{"implementation":"def solve(case):
    initial = case["initial_state"]
    max_steps = case["max_steps"]
    tool_obs = case["tool_observations"]
    trans = case["transitions"]
    current = initial
    trace = []
    step = 0
    while True:
        state_def = trans[current]
        if state_def["kind"] == "final":
            return {"final": state_def["value"], "status": "completed", "trace": trace}
        elif step >= max_steps:
            return {"final": None, "status": "max_steps_exceeded", "trace": trace}
        else:
            action = state_def["action"]
            observation = tool_obs[action]
            next_state = state_def["next_by_observation"].get(observation, state_def["default_next"])
            trace.append({"step": step, "action": action, "observation": observation, "state": next_state})
            current = next_state
            step += 1
"}
